package net.civeira.phylax.features.access.userprofile.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UpdatedAtVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property updated at of user profile ")
  void test_updated_at_v_o_builder() {
    Assertions.assertFalse(UpdatedAtVO.nullValue().getUpdatedAt().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(UpdatedAtVO.tryFrom(null).getUpdatedAt().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", UpdatedAtVO.from("one").getUpdatedAt().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UpdatedAtVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", UpdatedAtVO.from("one").toString());
  }
}
